<?php $isDisposed = $asset['status'] === 'disposed'; $hasInvoice = trim((string)($asset['invoiceNumber'] ?? '')) !== '' || !empty($asset['invoiceId']); ?>
<section class="heading">
    <div><p class="eyebrow"><?= $asset['classification']==='small'?'Bem de pequeno valor':'Ativo Fixo' ?></p><h1><?= h($asset['name']) ?></h1><p><?= h($asset['category']) ?> · <?= h($asset['location']) ?> · Patrimônio <?= h($asset['patrimony'] ?: 'não informado') ?></p></div>
    <div class="actions"><?php if (can('edit_assets')): ?><a class="button primary" href="<?= h(page_url('asset-edit',['id'=>(int)$asset['id']])) ?>"><?= $hasInvoice ? 'Editar dados' : 'Editar ativo sem NF-e' ?></a><?php endif; ?><a class="button" href="<?= h(page_url('assets')) ?>">Voltar</a></div>
</section>
<section class="panel"><div class="panel-head"><div><h2>Dados do ativo</h2><p>Origem e vínculo fiscal são preservados.</p></div><span class="badge <?= $isDisposed?'red':'green' ?>"><?= h(status_label($asset['status'])) ?></span></div><div class="panel-body form-grid">
    <div><span class="hint">Patrimônio</span><p><strong><?= h($asset['patrimony'] ?: '—') ?></strong></p></div><div><span class="hint">Classe / condição</span><p><?= $asset['classification']==='small'?'Bem de pequeno valor':'Ativo Fixo' ?> · <?= h($asset['condition']) ?></p></div>
    <div><span class="hint">Marca / tipo / cor</span><p><?= h($asset['brand'] ?: '—') ?> · <?= h($asset['type'] ?: '—') ?> · <?= h($asset['color'] ?: '—') ?></p></div><div><span class="hint">Aquisição / nota</span><p><?= h(date_br($asset['acquiredAt'])) ?> · <?= h(asset_invoice_display_label($asset)) ?></p></div>
    <div><span class="hint">Quantidade / valor histórico</span><p><?= h($asset['quantity'] ?? '—') ?> · <?= h(money_br($asset['value'])) ?></p></div><div><span class="hint">Vida útil / ano de compra</span><p><?= h($asset['usefulLife'] ?? '—') ?> anos · <?= h($asset['purchaseYear'] ?? '—') ?></p></div>
    <div class="span-2"><span class="hint">Descrição original</span><p><?= nl2br(h($asset['originalDescription'])) ?></p></div>
    <?php if ($asset['notes']!==''): ?><div class="span-2"><span class="hint">Observações</span><p><?= nl2br(h($asset['notes'])) ?></p></div><?php endif; ?>
    <?php if ($isDisposed): ?><div><span class="hint">Baixa em</span><p><?= h(date_br($asset['disposalDate'])) ?></p></div><div><span class="hint">Motivo</span><p><?= nl2br(h($asset['disposalReason'])) ?></p></div><?php endif; ?>
</div></section>
<?php if (!$isDisposed && can('edit_assets')): ?><section class="panel"><div class="panel-head"><div><h2>Registrar baixa</h2><p>O ativo permanece no histórico; informe a data e o motivo.</p></div></div><div class="panel-body"><form method="post" action="index.php" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="dispose-asset"><input type="hidden" name="id" value="<?= (int)$asset['id'] ?>"><label class="field"><span>Data da baixa</span><input type="date" name="disposalDate" required></label><label class="field"><span>Motivo da baixa</span><input name="disposalReason" required maxlength="2000"></label><div class="span-2"><button class="button danger" type="submit">Confirmar baixa</button></div></form></div></section><?php elseif (!$isDisposed): ?><p class="notice">Esta conta está em modo de consulta para este ativo; não pode editar nem registrar uma baixa.</p><?php endif; ?>
<?php if (can('manage_users') && can('edit_assets')): ?>
<section class="panel" id="excluir">
    <div class="panel-head"><div><h2>Excluir ativo</h2><p>Informe o motivo. O registro sairá das listas e relatórios; a NF-e, seus itens e o XML original serão preservados.</p></div></div>
    <div class="panel-body"><form method="post" action="index.php" class="form-grid" data-confirm-submit="Confirma a exclusão permanente deste ativo? O motivo ficará registrado no histórico administrativo; a NF-e será preservada."><?= csrf_field() ?><input type="hidden" name="action" value="delete-asset"><input type="hidden" name="id" value="<?= (int)$asset['id'] ?>"><label class="field span-2"><span>Motivo da exclusão</span><textarea name="reason" required maxlength="2000"></textarea></label><div class="span-2"><button class="button danger" type="submit">Excluir ativo</button></div></form></div>
</section>
<?php endif; ?>
